function createCardElement(card) {
    const cardEl = document.createElement('div');
    cardEl.className = 'card';
    cardEl.setAttribute('draggable', 'true');
    cardEl.dataset.id = card.id;
    cardEl.id = `card-${card.id}`;

    // Eventos de arrastre
    cardEl.addEventListener('dragstart', (e) => {
        e.dataTransfer.setData('text/plain', card.id);
        e.dataTransfer.effectAllowed = 'move';
        setTimeout(() => cardEl.classList.add('dragging'), 0); // Aplicar clase de dragging
    });

    cardEl.addEventListener('dragend', () => {
        cardEl.classList.remove('dragging');
    });


    // Determinar la clase y el texto del badge de prioridad
    let priorityBadgeHTML = '';
    const getPriorityStyle = (priority) => {
        switch (priority.toLowerCase()) {
            case 'alta': return { text: 'alta', class: 'bg-red' };
            case 'media': return { text: 'media', class: 'bg-yellow' };
            case 'baja': return { text: 'baja', class: 'bg-green' };
            default: return { text: '', class: '' };
        }
    };

    const priorityStyle = getPriorityStyle(card.priority);
    if (priorityStyle.text) {
        priorityBadgeHTML = `<span class="priority-badge ${priorityStyle.class}">${priorityStyle.text}</span>`;
    }


    // Contenido principal de la tarjeta
    let bodyHTML = `
        <div class="card-header">
            <strong>${card.title}</strong>
            ${priorityBadgeHTML}
        </div>
        <p style="font-size:0.9em; margin-top: 5px;">${card.body}</p>
    `;

    // Botones de acciones (solo se muestran al pasar el mouse)
    const actionsHTML = `
        <div class="card-actions">
            <button class="action-btn edit-btn" onclick="openModal('${card.id}', '${card.status}')">✏️ Editar</button>
            <button class="action-btn delete-btn" onclick="deleteCard('${card.id}', '${card.status}')">🗑️ Eliminar</button>
        </div>`;

    cardEl.innerHTML = bodyHTML + actionsHTML;
    return cardEl;
}
