function getPriorityClass(priority) {
    const lowerCasePriority = priority ? priority.toLowerCase() : 'media';
    switch (lowerCasePriority) {
        case 'alta':
            return 'priority-high'; // Rojo
        case 'media':
            return 'priority-medium'; // Amarillo
        case 'baja':
            return 'priority-low'; // Verde
        default:
            return '';
    }
}
