### FUNCION: renderAllCards
```javascript
/** Limpia y vuelve a renderizar todas las tarjetas en el DOM */
function renderAllCards() {
    // 1. Limpiar contenedores existentes
    ['pendiente', 'encourso', 'completado'].forEach(status => {
        document.getElementById(`cards-contenedor-${status}`).innerHTML = '';
    });

    // Función auxiliar para asignar valor numérico de prioridad (Alta > Media > Baja)
    const getPriorityValue = (priority) => {
        switch (priority) {
            case 'alta': return 3;
            case 'media': return 2;
            case 'baja': return 1;
            default: return 0;
        }
    };

    // 2. Renderizar tarjetas y actualizar contadores
    for (const status in kabanBoardState) {
        let containerEl = document.getElementById(`cards-contenedor-${status}`);
        let countSpan = document.querySelector(`#${status} .card-count`);

        if (!containerEl || !countSpan) continue;

        // *** CORRECCIÓN: Ordenar las tarjetas antes de renderizarlas ***
        const cardsToRender = [...kabanBoardState[status]]; // Clonar para no modificar el estado global directamente
        cardsToRender.sort((a, b) => {
            const pA = getPriorityValue(a.priority);
            const pB = getPriorityValue(b.priority);

            // 1. Ordenar por Prioridad (Descendente: Alta > Media > Baja)
            if (pA !== pB) {
                return pB - pA; // Si pB es mayor, b va primero
            }

            // 2. Si la prioridad es igual, ordenar por tiempo (Descendente: Más reciente primero)
            // Asumimos que 'timestamp' existe y se actualiza en creación/movimiento.
            return b.timestamp - a.timestamp;
        });


        // Renderizar cada tarjeta del estado en su contenedor correspondiente
        cardsToRender.forEach(card => {
            const cardElement = createCardElement(card);
            containerEl.appendChild(cardElement);
        });

        // Actualizar el contador de la columna
        countSpan.textContent = `(${kabanBoardState[status].length})`;
    }
}
```

